package dev.eugheist.tc4modern;
import net.minecraft.world.item.*;import net.minecraft.world.level.Level;import net.minecraft.world.entity.*;import thaumcraft.api.aspects.*;
public final class ManaBeanItem extends Item {
 public ManaBeanItem(Properties p){super(p.food(new net.minecraft.world.food.FoodProperties.Builder().nutrition(1).saturationModifier(.5f).alwaysEdible().fast().build()));}
 public static ItemStack of(Aspect a,int count){var s=new ItemStack(BasicsContent.MANA_BEAN.get(),count);var t=NoteData.tag(s);new AspectList().add(a,1).writeToNBT(t);s.set(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(t));return s;}
 public static Aspect aspect(ItemStack s){var al=new AspectList();al.readFromNBT(NoteData.tag(s));return al.size()>0?al.getAspects()[0]:null;}
 @Override public int getUseDuration(ItemStack s,LivingEntity e){return 10;}
 @Override public void inventoryTick(ItemStack s,Level l,Entity e,int slot,boolean selected){if(!l.isClientSide&&aspect(s)==null){var aa=Aspect.aspects.values().toArray(Aspect[]::new);var t=NoteData.tag(of(aa[l.random.nextInt(aa.length)],1));s.set(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(t));}}
 @Override public ItemStack finishUsingItem(ItemStack s,Level l,LivingEntity e){var a=aspect(s);if(!l.isClientSide&&e instanceof net.minecraft.server.level.ServerPlayer player){var effect=BasicsPotionSlots.pick(l.random.nextInt(40));if(effect!=null){if(effect.value().isInstantenous())effect.value().applyInstantenousEffect(player,player,player,2,3);else player.addEffect(new net.minecraft.world.effect.MobEffectInstance(effect,160+l.random.nextInt(80),0));}if(a!=null&&l.random.nextFloat()<.25f){var k=ResearchKnowledge.load(player.getPersistentData());k.addAspectPool("current",a,(short)1);ResearchKnowledge.save(player.getPersistentData(),k);ThaumometerItem.sync(player,"");AspectGain.send(player,a,1);}}return super.finishUsingItem(s,l,e);}
 @Override public net.minecraft.world.InteractionResult useOn(net.minecraft.world.item.context.UseOnContext c){var l=c.getLevel();var p=c.getClickedPos().below();if(c.getClickedFace()!=net.minecraft.core.Direction.DOWN||!l.getBlockState(p).isAir()||!BasicsContent.MANA_POD.get().defaultBlockState().canSurvive(l,p)||c.getPlayer()==null||!c.getPlayer().mayUseItemAt(p,c.getClickedFace(),c.getItemInHand()))return net.minecraft.world.InteractionResult.PASS;if(!l.isClientSide){l.setBlock(p,BasicsContent.MANA_POD.get().defaultBlockState(),3);if(l.getBlockEntity(p) instanceof ManaPodEntity pod){pod.aspect=aspect(c.getItemInHand());pod.changed();}if(!c.getPlayer().getAbilities().instabuild)c.getItemInHand().shrink(1);}return net.minecraft.world.InteractionResult.sidedSuccess(l.isClientSide);}
}
